import React from "react";

// Dummy issues and technicians (can be replaced with backend data)
export const initialIssues = [
  {
    title: "Water leak in bathroom",
    description: "The bathroom sink is leaking continuously",
    location: "Block A - Floor 3 - Unit 301",
    tags: ["URGENT", "IN PROGRESS"],
    assignees: [],
    overdue: true,
    time: "4d 6h",
  },
  {
    title: "Broken door lock",
    description: "Main door lock is broken and needs urgent replacement",
    location: "Block B - Floor 2 - Unit 205",
    tags: ["MEDIUM", "PENDING"],
    assignees: [],
    overdue: false,
    time: "1d 2h",
  },
  {
    title: "Power outage in unit",
    description: "No power in the entire unit, possible circuit issue",
    location: "Block A - Floor 5 - Unit 502",
    tags: ["URGENT", "ASSIGNED"],
    assignees: [],
    overdue: true,
    time: "3d 23h",
  },
  {
    title: "Paint peeling in living room",
    description: "Paint is peeling off the living room wall",
    location: "Block C - Floor 1 - Unit 103",
    tags: ["LOW", "PENDING"],
    assignees: [],
    overdue: true,
    time: "4h",
  },
  {
    title: "HVAC not cooling",
    description: "AC is running but not cooling the room",
    location: "Block B - Floor 4 - Unit 408",
    tags: ["HIGH", "COMPLETED"],
    assignees: [],
    overdue: false,
    time: "-",
  },
];

const technicians = [
  { name: "Patrick Niyonsenga", email: "patrick.n@propcare.rw" },
  { name: "Eric Habimana", email: "eric.h@propcare.rw" },
  { name: "Jean Baptiste", email: "jean.b@propcare.rw" },
];

const tagColors = {
  URGENT: "bg-red-100 text-red-700",
  "IN PROGRESS": "bg-blue-100 text-blue-700",
  COMPLETED: "bg-green-100 text-green-700",
  MEDIUM: "bg-yellow-100 text-yellow-700",
  ASSIGNED: "bg-gray-100 text-gray-600",
  LOW: "bg-gray-100 text-gray-600",
  PENDING: "bg-gray-100 text-gray-600",
  HIGH: "bg-yellow-100 text-yellow-700",
};

export default function ManagementIssues({ issues, setIssues }) {
  const [assigning, setAssigning] = React.useState(null); // index of issue being assigned

  const handleAssignClick = idx => {
    setAssigning(idx);
  };

  const handleAssignTech = (idx, techName) => {
    setIssues(prev => prev.map((issue, i) => {
      if (i !== idx) return issue;
      if (issue.assignees.includes(techName)) return issue;
      return { ...issue, assignees: [...issue.assignees, techName] };
    }));
    setAssigning(null);
  };

  return (
    <div className="bg-white rounded-2xl shadow p-0 mb-6 md:mb-8 w-full">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between px-4 md:px-6 pt-4 md:pt-6 pb-2 gap-2">
        <span className="text-lg md:text-xl font-semibold flex items-center gap-2">
          All Issues
        </span>
      </div>
      <div className="px-4 md:px-6 pb-4">
        {issues.map((issue, idx) => (
          <div className="flex flex-col md:flex-row items-start justify-between border-t border-gray-100 py-4 md:py-5 gap-4 md:gap-6 transition hover:bg-gray-50" key={idx}>
            <div className="flex-1">
              <div className="text-base md:text-lg font-semibold mb-1">{issue.title}</div>
              <div className="text-gray-500 mb-2">{issue.location}</div>
              <div className="text-gray-600 mb-2 text-sm">{issue.description}</div>
              <div className="flex gap-2 mb-1 flex-wrap">
                {issue.tags.map((tag, i) => (
                  <span className={`rounded-md px-2 md:px-3 py-1 text-xs md:text-sm font-medium ${tagColors[tag] || 'bg-gray-100 text-gray-700'}`} key={i}>{tag}</span>
                ))}
              </div>
              {/* Assignment UI */}
              <div className="mt-2">
                {issue.assignees.length > 0 && (
                  <span className="inline-flex flex-wrap gap-1 mr-2">
                    {issue.assignees.map(name => (
                      <span key={name} className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-medium">{name}</span>
                    ))}
                  </span>
                )}
                {assigning === idx ? (
                  <div className="flex items-center gap-2">
                    <select
                      className="border rounded px-2 py-1 text-sm"
                      onChange={e => handleAssignTech(idx, e.target.value)}
                      defaultValue=""
                    >
                      <option value="" disabled>Select technician</option>
                      {technicians.map(t => (
                        <option key={t.email} value={t.name}>{t.name}</option>
                      ))}
                    </select>
                    <button className="text-xs px-2 py-1 bg-gray-200 rounded" onClick={() => setAssigning(null)}>Cancel</button>
                  </div>
                ) : (
                  <button className="text-xs px-3 py-1 bg-indigo-100 text-indigo-700 rounded hover:bg-indigo-200 font-medium" onClick={() => handleAssignClick(idx)}>Assign Technician</button>
                )}
              </div>
            </div>
            <div className="flex flex-col items-end min-w-[70px] md:min-w-[90px] gap-1">
              {issue.time && (
                <span className="flex items-center gap-1 text-yellow-700 text-xs md:text-base font-medium"><span role="img" aria-label="warning">⚠️</span> {issue.time}</span>
              )}
              {issue.overdue && <span className="text-red-600 text-xs md:text-sm font-semibold">overdue</span>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
